update public.study_sets set units = units || (
  select coalesce(jsonb_agg(x), '[]'::jsonb) from jsonb_array_elements('[{"u": 7, "name": "Over, through & across"},{"u": 8, "name": "Around, about & along"},{"u": 9, "name": "Into, onto & to"},{"u": 10, "name": "At, by, from & more"}]'::jsonb) x
   where not exists (select 1 from jsonb_array_elements(units) o where (o->>'u')::int = (x->>'u')::int))
 where id = '00000000-0000-4000-8000-00000000f4a5';

