  ('Hold out on', '', 'Not pay someone or give them information.', 'He''s been [holding out on] me for weeks and I really need the money.', '🔛', array['Phrasal verb','Action','Money & work']::text[]),
  ('Hold over', '', 'Delay.', 'The meeting has been [held over] till Friday.', '🌉', array['Phrasal verb','Action','Time & change']::text[]),
  ('Hold over', 'meaning 2', 'To continue something for longer than planned.', 'It has been so successful that they have [held] it [over] for another fortnight.', '🌉', array['Phrasal verb','Action','Time & change','≈ Without stopping']::text[]),
  ('Hold together', '', 'Not break up.', 'The society managed to [hold together] despite the crisis.', '📌', array['Phrasal verb','Action','How things are done']::text[]),
  ('Hold up', '', 'Delay when travelling.', 'I was [held up] by the terrible traffic and arrived half an hour late for my appointment.', '⬆️', array['Phrasal verb','Action','Time & change']::text[]),
  ('Hold up', 'meaning 2', 'Rob with violence or threats thereof.', 'Two armed men [held up] the bank in High Street this morning and got away with £75,000.', '⬆️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Hold with', '', 'Accept (usually negative).', 'I don''t [hold with] their plans.', '🔗', array['Phrasal verb','Action','How things are done','≈ Agreed']::text[]),
  ('Hole up', '', 'Hide to avoid detection or an unpleasant situation.', 'They [holed up] in a remote cottage while the police were searching for them.', '⬆️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Home in on', '', 'Target.', 'The government is [homing in on] benefit fraud.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Hone in on', '', 'Target, focus.', 'The company [honed in on] its rival and tried to take it over.(Some consider this verb to be wrong and that is confused with ''home in on.).', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Hook into', '', 'Persuade someone to do something they don''t want to do.', 'She [hooked] them [into] coming after all.', '➡️', array['Phrasal verb','Action','How things are done','≈ Want']::text[]),
  ('Hook up', '', 'Meet someone.', 'We [hooked up] at the conference.', '⬆️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Hook up to', '', 'Connect to a machine.', 'He''s [hooked up to] a ventilator in the hospital.', '➡️', array['Phrasal verb','Action','How things are done','≈ Join']::text[]),
  ('Hoon around', '', 'Act in a dangerous or reckless way, especially when driving fast.', 'He was [hooning around] in his new car last night and the police pulled him.', '🔄', array['Phrasal verb','Action','How things are done','≈ Angry','≈ Dangerous']::text[]),
  ('Horse around', '', 'Not be serious.', 'The class were [horsing around] when the teacher came in and told them to sit down.', '🔄', array['Phrasal verb','Action','How things are done']::text[]),
  ('Hose down', '', 'Use a hose to wet, clean or wash something.', 'They [hosed] the patio [down].', '⬇️', array['Phrasal verb','Action','Homes & buildings']::text[]),
  ('Hose down', 'meaning 2', 'Invest heavily in or throw a lot of money at something.', 'They have [hosed down] an obscure start-up up with capital.', '⬇️', array['Phrasal verb','Action','Money & work']::text[]),
  ('Hound out', '', 'Force someone out of a place, job, position, etc.', 'The press [hounded] the minister [out] after the scandal broke.', '📤', array['Phrasal verb','Action','Money & work','Places & travel']::text[]),
  ('Hover around', '', 'Move about a place.', 'She was [hovering around] to see what we were talking about.', '🔄', array['Phrasal verb','Action','Ways of moving','Places & travel']::text[]),
  ('Hunker down', '', 'Settle in a place as comfortably as possible to stay there.', 'The troops [hunkered down] in the building.', '⬇️', array['Phrasal verb','Action','Places & travel']::text[]),
  ('Hunt out', '', 'Search until you find something.', 'It took me ages to [hunt out] the photos.', '📤', array['Phrasal verb','Action','Looking & seeing','≈ Look']::text[]),
  ('Hunt up', '', 'Search for and manage to find something.', 'He [hunted up] a copy the book in the British library.', '⬆️', array['Phrasal verb','Action','Looking & seeing','≈ Look','≈ Leaders']::text[]),
  ('Hush up', '', 'Try to keep something bad from becoming widely known.', 'The company tried to [hush up] the scandal, but it still got into the newspapers.', '⬆️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Iron out', '', 'Remove small problems or irregularities.', 'The management team [ironed out] the tax problems before they gave the project the [ok].', '📤', array['Phrasal verb','Action','Size, amount & distance']::text[]),
  ('Issue forth', '', 'Come out of a place.', 'New initiatives [issue forth] from the government on a daily basis.', '📌', array['Phrasal verb','Action','Ways of moving','Places & travel']::text[]),
  ('Jabber away', '', 'Talk fast or incomprehensibly.', 'They started [jabbering away] about file systems and lost me completely.', '↔️', array['Phrasal verb','Action','Saying & thinking']::text[]),
  ('Jack around', '', 'Make trouble for someone, fail to keep promises.', 'Don''t listen to him-he always [jacks] people [around].', '🔄', array['Phrasal verb','Action','How things are done','≈ Fail']::text[]),
  ('Jack in', '', 'Quit, give up.', 'I [jacked] my job [in] because my boss refused to give me a raise.', '↔️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Jack up', '', 'Raise a car to be able to do mechanical work.', 'We [jacked] the car [up] and changed the tyre.', '⬆️', array['Phrasal verb','Action','Money & work','Places & travel']::text[]),
  ('Jack up', 'meaning 2', 'Increase sharply.', 'They have [jacked up] the price of oil this month.', '⬆️', array['Phrasal verb','Action','Size, amount & distance']::text[]),
  ('Jam on', '', 'Apply or operate something forcefully.', 'Jack [jammed on] the brakes when the rabbit ran in front of his car.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Jaw away', '', 'Talk just for the point of talking rather than having anything to say.', 'That shows that your interest is not in helping the student, but in [jawing away].', '↔️', array['Phrasal verb','Action','Saying & thinking']::text[]),
  ('Jazz up', '', 'Make something more interesting or attractive.', 'The show was getting stale so they [jazzed] it [up] with some new scenes.', '⬆️', array['Phrasal verb','Action','Size, amount & distance','≈ Curious']::text[]),
  ('Jerk around', '', 'Cause someone trouble, treat someone badly.', 'He was [jerking] us [around] and wouldn''t give us the facts.', '🔄', array['Phrasal verb','Action','How things are done']::text[]),
  ('Jerk around', 'meaning 2', 'Behave stupidly.', 'They were [jerking around] during the lecture.', '🔄', array['Phrasal verb','Action','Character']::text[]),
  ('Joke around', '', 'Be funny, or try to.', 'He''s always [joking around] in class.', '🔄', array['Phrasal verb','Action','How things are done']::text[]),
  ('Jot down', '', 'Make a quick note.', 'I [jotted down] her number on a scrap of paper and I can''t find it now.', '⬇️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Juice up', '', 'Make something more exciting or perform better.', 'I need to buy some memory to [juice] my computer [up].', '⬆️', array['Phrasal verb','Action','Size, amount & distance']::text[]),
  ('Jump at', '', 'Accept eagerly.', 'I''d [jump at] the chance to go and live in Japan.', '📌', array['Phrasal verb','Action','How things are done','≈ Agreed']::text[]),
  ('Jump in', '', 'Enter a conversation.', 'He [jumped in] and told them exactly what he thought.', '↔️', array['Phrasal verb','Action','Ways of moving']::text[]),
  ('Jump off', '', 'Start quickly, often well.', 'The [ipo jumped off] on the first day.', '🔛', array['Phrasal verb','Action','Time & change','≈ Hurrying']::text[]),
  ('Jump on', '', 'Criticize, attack.', 'Everyone [jumped on] me when I raised the issue.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Keel over', '', 'Turn upside down.', 'The boat [keeled over] in the storm and the crew drowned.', '🌉', array['Phrasal verb','Action','How things are done']::text[]),
  ('Keel over', 'meaning 2', 'Surrender, give in.', 'He was going to confront his boss, but [keeled over] and didn''t mention the matter.', '🌉', array['Phrasal verb','Action','How things are done']::text[]),
  ('Keel over', 'meaning 3', 'Fall to the ground.', 'The drunk [keeled over] when trying to leave the pub.', '🌉', array['Phrasal verb','Action','Ways of moving']::text[]),
  ('Keep around', '', 'Keep something near you.', 'I [keep] a dictionary [around] when I''m doing my homework.', '🔄', array['Phrasal verb','Action','How things are done']::text[]),
  ('Keep at', '', 'Continue with something difficult.', 'She found the course hard but she [kept at] it and completed it successfully.', '📌', array['Phrasal verb','Action','Time & change','≈ Without stopping']::text[]),
  ('Keep away', '', 'Don''t allow someone near something.', 'Medicines should always be [kept away] from children.', '↔️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Keep back', '', 'Maintain a safe distance.', 'The police told the crowd to [keep back] from the fire.', '↔️', array['Phrasal verb','Action','Danger & safety','Size, amount & distance']::text[]),
  ('Keep from', '', 'Control yourself, refrain.', 'I couldn''t [keep from] arguing with her.', '📌', array['Phrasal verb','Action','How things are done','≈ Leaders']::text[]),
  ('Keep in', '', 'Not allow someone out.', 'The teacher [kept] the students [in] after school because they had misbehaved.', '↔️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Keep off', '', 'Not talk about.', 'She [kept off] the subject of her.', '🔛', array['Phrasal verb','Action','Saying & thinking']::text[]),
  ('Keep off', 'meaning 2', 'Not tread on something.', '[Keep off] the grass in the park, please.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Keep on', '', 'Continue.', 'He [kept on] trying and succeeded in the end.', '🔛', array['Phrasal verb','Action','Time & change','≈ Without stopping']::text[]),
  ('Keep out', '', 'Not allow someone to enter.', 'The police [kept] the demonstrators [out] of the building.', '📤', array['Phrasal verb','Action','Ways of moving']::text[]),
  ('Keep to', '', 'Stay within limits.', 'Please [keep to] the path.', '➡️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Keep up', '', 'Not let someone go to bed.', 'My neighbours [kept] me [up] till after 4 am with their loud music last night.', '⬆️', array['Phrasal verb','Action','Ways of moving']::text[]),
  ('Keep up', 'meaning 2', 'Maintain a continuous action, persist.', 'First I phoned you and left a message that you should phone me; then you phoned and I was out, so you left a message; then...! How long can we [keep] this [up] without ever speaking to each other directly?', '⬆️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Keep up at', '', 'Continue, not quit.', 'Learning a language is difficult, but if you [keep up at] it, you''ll succeed in the end.', '📌', array['Phrasal verb','Action','Time & change','≈ Without stopping']::text[]),
