  ('Keep up with', 'meaning 2', 'Stay up to date.', 'It''s hard to [keep up with] all the latest improvements and breakthroughs in technology nowadays.', '🔗', array['Phrasal verb','Action','How things are done']::text[]),
  ('Key down', '', 'Relax, unwind.', 'I need to [key down] before I go to bed.', '⬇️', array['Phrasal verb','Action','How things are done','≈ Calm']::text[]),
  ('Key in', '', 'Enter numbers or information into a computer or electronic system.', 'It took me ages to [key in] all the information into the database.', '↔️', array['Phrasal verb','Action','Ways of moving']::text[]),
  ('Key in on', '', 'Focus attention on, single out.', 'They [keyed in on] the person they believed had done it.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Key on', '', 'Target, focus on (sport).', 'We will [key on] the opposing team''s lack of skills on defense.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Key to', '', 'Plan things to fit or suit people or situations.', 'Promotions are [keyed to] people''s abilities.', '➡️', array['Phrasal verb','Action','Saying & thinking']::text[]),
  ('Key up', '', 'Make someone excited or nervous.', 'The noise got us [keyed up].', '⬆️', array['Phrasal verb','Action','Feelings & moods','≈ Excited']::text[]),
  ('Kick about', '', 'Discuss.', 'We [kicked] the idea [about] at the meeting.', '🔄', array['Phrasal verb','Action','Saying & thinking']::text[]),
  ('Kick around', '', 'Discuss.', 'We [kicked] the idea [around].', '🔄', array['Phrasal verb','Action','Saying & thinking']::text[]),
  ('Kick around with', '', 'Spend time with.', 'I used to [kick around with] them, but haven''t seen them for a while.', '🔗', array['Phrasal verb','Action','Money & work','Time & change']::text[]),
  ('Kick back', '', 'Pay someone illegally as part of the price.', 'I had to [kick] ten percent [back] to the government official to get the contract.', '↔️', array['Phrasal verb','Action','Money & work']::text[]),
  ('Kick back', 'meaning 2', 'Resist.', 'They [kicked back] when we suggested downsizing.', '↔️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Kick back', 'meaning 3', 'Relax.', 'Rather than go out tonight, we plan to [kick back] and watch television.', '↔️', array['Phrasal verb','Action','How things are done','≈ Calm']::text[]),
  ('Kick down', '', 'Break something with your feet.', 'The police [kicked] the door [down].', '⬇️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Kick in', '', 'Break something with your feet.', 'They [kicked] his head [in].', '↔️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Kick in', 'meaning 2', 'Contribute money.', 'I’ll [kick in] for some of the beer if you will buy the pizza.', '↔️', array['Phrasal verb','Action','Money & work']::text[]),
  ('Kick in', 'meaning 3', 'Start having an effect.', 'The budget cuts are starting to [kick in] and people are struggling.', '↔️', array['Phrasal verb','Action','Time & change']::text[]),
  ('Kick off', '', 'Start a game of football.', 'The match [kicks off] at three o''clock.', '🔛', array['Phrasal verb','Action','Time & change']::text[]),
  ('Kick off', 'meaning 2', 'Die.', 'He [kicked off] last month when he had a massive heart attack.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Kick off', 'meaning 3', 'When trouble starts.', 'The fight [kicked off] when he insulted the guy''s girlfriend.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Kick off', 'meaning 4', 'Argue, protest and refuse to co-operate.', 'He started [kicking off] big time when the police tried to arrest him.', '🔛', array['Phrasal verb','Action','Saying & thinking','≈ Rejected']::text[]),
  ('Kick out', '', 'Expel.', 'The family [kicked] the au pair [out] when they found out that she was planning to move to work for another household.', '📤', array['Phrasal verb','Action','How things are done']::text[]),
  ('Kick up', '', 'Cause trouble or pain.', 'My back [kicks up] when it gets cold.', '⬆️', array['Phrasal verb','Action','Health & body']::text[]),
  ('Kip down', '', 'Sleep away from your home, often without planning to.', 'It''s too late to get the train, so can I [kip down] here tonight?', '⬇️', array['Phrasal verb','Action','Health & body','Homes & buildings']::text[]),
  ('Kip down on', '', 'Sleep on something other than a bed.', 'There were so many of us that we had to [kip down on] the floor.', '🔛', array['Phrasal verb','Action','Health & body']::text[]),
  ('Kiss off', '', 'Used to tell someone to go away.', 'He was bugging us, so we told him to [kiss off].', '🔛', array['Phrasal verb','Action','Ways of moving','Saying & thinking']::text[])) as v(h, s, m, e, j, tg)
